import sys

MOD = 998244353

def pow_mod(base, exp):
    res = 1
    while exp > 0:
        if exp & 1:
            res = (res * base) % MOD
        base = (base * base) % MOD
        exp >>= 1
    return res

def mod_exp(base, exp):
    result = 1
    base %= MOD
    while exp > 0:
        if exp & 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exp >>= 1
    return result

class Matrix:
    def __init__(self, m):
        self.mat = m

    def multiply(self, other):
        res = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    res[i][j] += self.mat[i][k] * other.mat[k][j]
                res[i][j] %= MOD
        return Matrix(res)

    def pow(self, power):
        result = Matrix([[1, 0], [0, 1]])
        base = Matrix([row[:] for row in self.mat])
        while power > 0:
            if power & 1:
                result = result.multiply(base)
            base = base.multiply(base)
            power >>= 1
        return result

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    L = int(input_data[2])
    R = int(input_data[3])

    total_length = R - L + 1

    if n % 2 == 1 and m % 2 == 1:
        print(mod_exp(total_length % MOD, n * m))
    else:
        if total_length % 2 == 0:
            val = pow_mod(total_length % MOD, n * m - 1)
            answer = val * (total_length // 2) % MOD
            print(answer)
        else:
            half = total_length // 2
            identity = Matrix([[1, 0], [0, 1]])
            matrix = Matrix([[half, half + 1], [half + 1, half]])
            result_matrix = matrix.pow(n * m)
            print(result_matrix.mat[0][0])

if __name__ == "__main__":
    main()

